INSERT INTO parametros (codigo,parametro,descripcion) VALUES
('GENERO','Masculino','Género Masculino'),
('GENERO','Femenino','Género femenino'),
('GENERO','Otro','Otro género');
INSERT INTO parametros (codigo,parametro,descripcion) VALUES
('CATLECTOR','Básico','Categoría de lector inicial. Puede pedir hasta 3 libros por 5 días.'),
('CATLECTOR','Avanzado','Lector avanzado. Ha respondido responsablemente a los préstamos anteriores, puede pedir hasta 7 libros por 7 días.'),
('CATLECTOR','Reducido','Lector limitado. Ha respondido con retraso o daño en los préstamos anteriores, puede pedir hasta 3 libros por 3 días.'),
('CATLECTOR','Bloqueado','Lector limitado. Lector reducido que persevera en el retraso o daño en los préstamos anteriores, NO puede pedir libros por el período de bloqueo.');
INSERT INTO parametros (codigo,parametro,descripcion) VALUES
('GENLIT','Narrativo','Relata una historia en la cual aparecen ciertos personajes en un tiempo y espacio determinados. Las descripciones son un punto central en este género, así como los diálogos y monólogos.'),
('GENLIT','Lírico','Transmite sentimientos y emociones a través de la voz lírica, ya sea en verso o en prosa, así mismo presenta la realidad desde su propia perspectiva.'),
('GENLIT','Dramático','También llamado teatral, se caracteriza por contener obras con situaciones y conflictos en las que se hace uso del diálogo, con el propósito de que sean representadas en un escenario frente al público.'),
('GENLIT','Didáctico','El género didáctico es de reciente aparición, en este se presenta un tema, se expresa una opinión o se divulgan enseñanzas e ideas con respecto a ese tema.');
INSERT INTO parametros (codigo,parametro,descripcion) VALUES
('SUBGEN','Novela','Género Narrativo. Obra literaria escrita en prosa que narra una historia ficticia o real con el fin de entretener y emocionar al lector.'),
('SUBGEN','Cuento','Género Narrativo. Narración breve de hechos reales o ficticios que tiene pocos personajes y un argumento sencillo.'),
('SUBGEN','Fábula','Género Narrativo. Relato breve, en prosa o en verso, protagonizado por animales o cosas que hablan y actúan como personas, y que termina con una enseñanza o moraleja.'),
('SUBGEN','Leyenda','Género Narrativo. Narración tradicional que mezcla hechos reales y sucesos fantásticos o sobrenaturales, transmitida de generación en generación.'),
('SUBGEN','Epopeya','Género Narrativo. Relato épico y extenso, escrito originalmente en verso o prosa, que narra las hazañas legendarias o históricas de un héroe que representa los valores de todo un pueblo.'),
('SUBGEN','Poema Épico','Género Narrativo. Relato largo escrito en verso que cuenta las hazañas heroicas y batallas de uno o varios personajes extraordinarios.'),
('SUBGEN','Égloga','Género Lírico. Poesía lírica de tema amoroso que se desarrolla en un ambiente campestre e idealizado, donde los protagonistas suelen ser pastores que dialogan o cantan sobre sus sentimientos.'),
('SUBGEN','Elegía','Género Lírico. Poesía lírica que expresa lamento, tristeza o nostalgia por la muerte de una persona o por la pérdida de algo valioso, como el tiempo, la vida o una ilusión.'),
('SUBGEN','Oda','Género Lírico. Poema largo que expresa admiración, amor o alegría hacia una persona, un objeto o un sentimiento importante.'),
('SUBGEN','Sátira','Género Lírico. Composición literaria que utiliza el humor, la ironía y la exageración para criticar, censurar o ridiculizar los defectos humanos, la política o la sociedad.'),
('SUBGEN','Soneto','Género Lírico. Composición poética clásica que consta de catorce versos endecasílabos (de once sílabas) distribuidos en cuatro estrofas: dos cuartetos y dos tercetos.'),
('SUBGEN','Madrigal','Género Lírico. Composición poética breve de tema amoroso.'),
('SUBGEN','Himno','Género Lírico. Composición poética que expresa sentimientos de alegría, devoción, gratitud o celebración, y que sirve para honrar a una deidad, a una persona ilustre o a una colectividad, como un país.'),
('SUBGEN','Tragedia','Género Dramático. Forma literaria de la Antigüedad que representa conflictos y sufrimiento humano con un desenlace fatal.'),
('SUBGEN','Comedia','Género Dramático. Género artístico y teatral caracterizado por obras de tono alegre, festivo y humorístico que buscan divertir al público y terminan con un desenlace feliz.'),
('SUBGEN','Drama','Género Dramático. Representa situaciones y conflictos de la vida humana a través de diálogos y acciones de los personajes.'),
('SUBGEN','Entremés','Género Dramático. Pieza teatral breve de carácter cómico y popular que se originó en España durante el Siglo de Oro.'),
('SUBGEN','Sainete','Género Dramático. Pieza teatral breve y cómica, generalmente en un solo acto, que retrata las costumbres, los vicios y el habla popular de las clases bajas.'),
('SUBGEN','Ensayo','Género Didático. Prosa de carácter didáctico y reflexivo donde el autor analiza, interpreta o evalúa un tema de libre elección desde un punto de vista personal y subjetivo.'),
('SUBGEN','Biografía','Género Didático. La biografía es un género literario narrativo y expositivo que cuenta la historia de la vida de una persona real.'),
('SUBGEN','Carta','Género Didático. Formato donde la comunicación se desarrolla mediante textos escritos dirigidos a un receptor ausente.'),
('SUBGEN','Diálogo','Género Didático. Obra escrita en prosa o en verso donde dos o más personajes intercambian ideas, reflexiones o argumentos de forma alternada.'),
('SUBGEN','Discurso','Género Didático. Forma de expresión formal y estructurada cuyo propósito principal es persuadir, conmover, informar o enseñar a un público, cuidando de manera especial los recursos estéticos y retóricos del lenguaje.'),
('SUBGEN','Oratoria','Género Didático. Escrito en prosa, engloba las obras concebidas principalmente para ser pronunciadas en público bajo normas retóricas específicas.'),
('SUBGEN','Artículo Científico','Género Didático. Informe escrito y publicado que comunica por primera vez los resultados de una investigación original, siguiendo normas rigurosas de la comunidad académica.');